package com.gazellio.platform.controller; import com.gazellio.platform.dto.ApiDtos.SettingsUpdateRequest; import com.gazellio.platform.service.SettingsService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import org.springframework.security.access.prepost.PreAuthorize; import java.util.*;
@RestController @RequestMapping("/api/settings") @RequiredArgsConstructor public class SettingsController {private final SettingsService service;@GetMapping public Map<String,String> get(){return service.get();}@PreAuthorize("hasAuthority('SETTINGS_MANAGE')") @PutMapping public Map<String,String> update(@RequestBody SettingsUpdateRequest req){return service.update(req);}}
